/**
 * 场景任务实现类
 *
 * @since 2025/08/22
 */
@Component
public class SceneTaskManageServiceImpl implements SceneAllocTaskServiceDelegate {
    private static final OssLog LOGGER = OssLogFactory.getLog(SceneTaskManageServiceImpl.class);

    private static final String ALLOC_PRE = "0";

    private static final String ALLOC_EVA = "1";

    private static final int GERION_CATEGORY_ID = 4;

    private static final int NO_TASK_CREATING_FLAG = 1;

    private static final String SCENE_TASK_CREATE_LOCK = "tocAllocEva.SceneTaskCreateLock";

    private static final String INFO_SPLIT = ",";

    private static final boolean SELECT_ABLE = true;

    @Autowired private SceneTaskManageDBMapper sceneTaskManageDBMapper;

    @Autowired private ScenesMgrDBMapper scenesMgrDBMapper;

    @Autowired private ScenesRegionService scenesRegionService;

    @Autowired private VenueAllocTaskService venueAllocTaskService;

    @Autowired private PanVenueAllocDBMapper panVenueAllocDBMapper;

    @Autowired private SceneTaskManagerUtils sceneTaskManagerUtils;

    @Autowired private SceneTaskManageCheckHelper sceneTaskManageCheckHelper;

    @Autowired private PanAllocTaskHelper panAllocTaskHelper;

    @Override
    public List<SceneTaskReturn> getSceneTasks() {
        List<SceneTaskReturn> sceneTaskReturns = sceneTaskManageDBMapper.getSceneTasks();
        for (SceneTaskReturn sceneTaskReturn : sceneTaskReturns) {
            ViewInfo viewInfo = new ViewInfo();
            List<ViewDetail> viewDetails = new ArrayList<>();
            String applicationViewId = sceneTaskManageDBMapper.getApplicationInfos(sceneTaskReturn.getEvaTaskId());
            if (applicationViewId != null) {
                String[] parts = applicationViewId.split(INFO_SPLIT);
                for (int i = 0; i < parts.length; i++) {
                    ViewDetail viewDetail = new ViewDetail();
                    int viewId = Integer.parseInt(parts[i].trim());
                    RuleType ruleTypeInfo = RuleType.getRuleTypeById(viewId);
                    viewDetail.setViewId(viewId);
                    viewDetail.setViewName(LocaleUtil.getMessage(ruleTypeInfo.getNameKey()));
                    viewDetail.setSelectAble(SELECT_ABLE);
                    viewDetails.add(viewDetail);
                }
                viewInfo.setApplicationInfos(viewDetails);
            }
            sceneTaskReturn.setViewInfo(viewInfo);
            sceneTaskManageDBMapper.updateTaskStatus(sceneTaskReturn);
        }
        setOnlyEvaCellNum(sceneTaskReturns);
        return sceneTaskReturns;
    }

    private void setOnlyEvaCellNum(List<SceneTaskReturn> sceneTaskReturns) {
        List<SceneTaskBasicInfo> basicInfos = sceneTaskManageDBMapper.getOnlyEvaSiteAndCellCount();
        Map<Integer, SceneTaskBasicInfo> basicInfoMap = basicInfos.stream()
            .collect(Collectors.toMap(SceneTaskBasicInfo::getEvaTaskId, basicInfo -> basicInfo, (v1, v2) -> v2));
        for (SceneTaskReturn sceneTaskReturn : sceneTaskReturns) {
            if (!sceneTaskReturn.getTaskFeature().contains(ALLOC_PRE) && basicInfoMap.containsKey(
                sceneTaskReturn.getEvaTaskId())) {
                SceneTaskBasicInfo basicInfo = basicInfoMap.get(sceneTaskReturn.getEvaTaskId());
                sceneTaskReturn.setGNodeBNumber(basicInfo.getGNodeBNumber());
                sceneTaskReturn.setCellNumber(basicInfo.getCellNumber());
            }
        }
    }

    @Override
    public void addSceneTasks(SceneTaskInfo sceneTaskInfo, TaskInfo taskInfo, List<BitPackageInfo> bitPackageInfos,
        List<BackgroundUserGroup> backgroundUserGroups, TemplateInfo templateInfo) throws ServiceException {
        LOGGER.info("SceneAllocService addSceneTasks taskName:{}", sceneTaskInfo.getTaskName());
        String timeStamp = DateTime.now().toString(DateTimeFormat.forPattern("yyyyMMddHHmmss"));
        int lockRes = scenesMgrDBMapper.tryLockSceneTask(SCENE_TASK_CREATE_LOCK, timeStamp);
        LOGGER.info("addSceneTasks lockRes:{}", lockRes);
        if (lockRes != NO_TASK_CREATING_FLAG) {
            throw new VisibleException(ErrorCode.ERROR,
                LocaleUtil.getMessage("prs.web.experienceAssurance.scene.task.multiInstance.limit"));
        }
        try {
            Scene scene = scenesMgrDBMapper.getScene(sceneTaskInfo.getSceneId());
            sceneTaskInfo.setSceneType(scene.getSceneType());
            sceneTaskManageCheckHelper.checkSceneTaskNumber(sceneTaskInfo.getTaskFeature());
            sceneTaskManageCheckHelper.checkSceneInfo(scene);
            sceneTaskManageCheckHelper.checkSceneTaskInfos(sceneTaskInfo, scene);
            sceneTaskManageCheckHelper.checkSceneTaskNameExists(sceneTaskInfo);
            createNewSceneTasks(sceneTaskInfo, taskInfo, bitPackageInfos, backgroundUserGroups, templateInfo);
        } finally {
            scenesMgrDBMapper.tryUnlockSceneTask(SCENE_TASK_CREATE_LOCK, timeStamp);
        }
    }

    /**
     * 新增任务
     *
     * @param sceneTaskInfo 场景任务信息
     * @param taskInfo 任务信息
     * @param bitPackageInfos 套餐信息
     * @param backgroundUserGroups 背景用户信息
     * @param templateInfo 模板信息
     * @throws ServiceException 异常
     */
    @Transactional
    public void createNewSceneTasks(SceneTaskInfo sceneTaskInfo, TaskInfo taskInfo,
        List<BitPackageInfo> bitPackageInfos, List<BackgroundUserGroup> backgroundUserGroups, TemplateInfo templateInfo)
        throws ServiceException {
        LOGGER.info("Creating Scene Task: {}, id: {}", sceneTaskInfo.getTaskName(), sceneTaskInfo.getSceneId());
        scenesRegionService.updateScenesRegionInfo();
        Scene scene = scenesMgrDBMapper.getScene(sceneTaskInfo.getSceneId());
        if (scene.getRelateRegionId() <= 0) {
            throw new VisibleException(ErrorCode.ERROR, LocaleUtil.getMessage("prs.scenesmgr.sceneRegionIdInvalid"));
        }
        SceneTaskBasicInfo basicInfo = sceneTaskManagerUtils.buildSceneTaskBasicInfo(sceneTaskInfo);
        sceneTaskInfo.setTaskId(sceneTaskManageDBMapper.getNewSceneTaskId());
        LOGGER.info("sceneId: {}, taskId: {}", sceneTaskInfo.getSceneId(), sceneTaskInfo.getTaskId());
        try {
            if (sceneTaskInfo.getTaskFeature().contains(ALLOC_PRE)) {
                if (sceneTaskInfo.getSceneType() == SceneTypeEnum.VENUE.getSceneType()) {
                    VenueAllocTaskParam venueAllocTaskParam = sceneTaskManagerUtils.buildVenueAllocTaskParam(
                        sceneTaskInfo, taskInfo, bitPackageInfos, backgroundUserGroups, scene);
                    int taskId = venueAllocTaskService.addOrUpdateTask(venueAllocTaskParam);
                    basicInfo.setAllocTaskId(taskId);
                }
                if (sceneTaskInfo.getSceneType() == SceneTypeEnum.SCENIC_SPOT.getSceneType()) {
                    List<TemplatePackageInfo> templatePackageInfos = sceneTaskManagerUtils.buildEvaPackageInfos(
                        sceneTaskInfo, bitPackageInfos);
                    basicInfo = sceneTaskManagerUtils.createOrModifySpotTemplate(sceneTaskInfo, templateInfo, scene,
                        templatePackageInfos, basicInfo);
                }
                // 泛场馆预估场景处理逻辑
                if (sceneTaskInfo.getSceneType() == SceneTypeEnum.TRANSPORT_HUB.getSceneType()) {
                    panAllocTaskHelper.createAndModifySceneTasks(sceneTaskInfo);
                    basicInfo.setAllocTaskId(sceneTaskInfo.getTaskId());
                }
            }
            if (sceneTaskInfo.getTaskFeature().contains(ALLOC_EVA)) {
                sceneTaskManageCheckHelper.checkEvaScene(sceneTaskInfo);
                sceneTaskManageCheckHelper.checkFlexObjectScale(templateInfo);
                basicInfo = sceneTaskManagerUtils.buildEvaTemplateInfoParam(sceneTaskInfo, bitPackageInfos,
                    templateInfo, scene, basicInfo);
            }
            sceneTaskManageDBMapper.saveTask(sceneTaskInfo, basicInfo, System.currentTimeMillis());
            writeCreateOrEditOperationLog(sceneTaskInfo.getTaskName(), Constants.OPERATION_LEVEL_SUCCESS, true);
        } catch (DataAccessException | VisibleException ex) {
            writeCreateOrEditOperationLog(sceneTaskInfo.getTaskName(), Constants.OPERATION_LEVEL_FAILED, true);
            throw ex;
        }
    }

    @Override
    public void modifyScenesTasks(SceneTaskInfo sceneTaskInfo, TaskInfo taskInfo, List<BitPackageInfo> bitPackageInfos,
        List<BackgroundUserGroup> backgroundUserGroups, TemplateInfo templateInfo) throws ServiceException {
        LOGGER.info("Modifying Scene Task: {}", sceneTaskInfo.getTaskName());
        int evaTasktatus = sceneTaskManageDBMapper.getEvaTaskStatus(sceneTaskInfo.getTaskId());
        Scene scene = scenesMgrDBMapper.getScene(sceneTaskInfo.getSceneId());
        sceneTaskInfo.setSceneType(scene.getSceneType());
        sceneTaskManageCheckHelper.checkSceneInfo(scene);
        sceneTaskManageCheckHelper.checkSceneTaskInfos(sceneTaskInfo, scene);
        sceneTaskManageCheckHelper.checkSceneTaskNameChange(sceneTaskInfo);
        try {
            SceneTaskBasicInfo basicInfo = sceneTaskManageDBMapper.queryBasicTaskInfoByTaskId(
                sceneTaskInfo.getTaskId());
            if (sceneTaskInfo.getTaskFeature().contains(ALLOC_EVA)) {
                sceneTaskManageCheckHelper.checkEvaScene(sceneTaskInfo);
                sceneTaskManageCheckHelper.checkFlexObjectScale(templateInfo);
                if (evaTasktatus != GERION_CATEGORY_ID) {
                    throw new VisibleException(ErrorCode.ERROR,
                        LocaleUtil.getMessage("prs.web.experienceAssurance.venue.fail.eva.task.uneditable"));
                }
                basicInfo = sceneTaskManagerUtils.buildEvaTemplateInfoParam(sceneTaskInfo, bitPackageInfos,
                    templateInfo, scene, basicInfo);
            }
            sceneTaskManageDBMapper.saveTask(sceneTaskInfo, basicInfo, System.currentTimeMillis());
            writeCreateOrEditOperationLog(sceneTaskInfo.getTaskName(), Constants.OPERATION_LEVEL_SUCCESS, false);
        } catch (DataAccessException ex) {
            writeCreateOrEditOperationLog(sceneTaskInfo.getTaskName(), Constants.OPERATION_LEVEL_FAILED, false);
            throw ex;
        }
    }

    private void writeCreateOrEditOperationLog(String venueName, int result, boolean isAdd) {
        String operation = isAdd
            ? LocaleUtil.getMessage("prs.scenealloc.creatTask")
            : LocaleUtil.getMessage("prs.scenealloc.editTask");
        String opResult = (result == Constants.OPERATION_LEVEL_SUCCESS
            ? LocaleUtil.getMessage("prs.venuealloc.success")
            : LocaleUtil.getMessage("prs.venuealloc.failed"));
        String detail = String.join(" ", operation, venueName, opResult);
        LogInfo logInfo = new LogInfo(operation, detail, LocaleUtil.getMessage("prs.tocallocvenue.scene.task.manage"),
            LocaleUtil.getMessage("prs.tocallocvenue.service.scene.task.manage"), result);
        OperationLogWriter.writeOperationLog(logInfo, AuditLogLevel.MAJOR.getValue(),
            isAdd ? OperationType.NEW : OperationType.MODIFY, AuditModule.MODULE_REPORT);
    }

    @Override
    @Transactional
    public void deleteScenesTasks(int[] taskIds) throws ServiceException {
        try {
            SceneTaskInfo sceneTaskInfo = sceneTaskManageDBMapper.getSceneInfoById(taskIds[0]);
            Integer evaTasktatus = sceneTaskManageDBMapper.getEvaTaskStatus(taskIds[0]);
            if (evaTasktatus == null) {
                throw new VisibleException(ErrorCode.ERROR,
                    LocaleUtil.getMessage("prs.web.experienceAssurance.scene.fail.sceneAlreadyDelete"));
            }
            if (evaTasktatus != GERION_CATEGORY_ID && sceneTaskInfo.getTaskFeature().contains(ALLOC_EVA)) {
                throw new VisibleException(ErrorCode.ERROR,
                    LocaleUtil.getMessage("prs.web.experienceAssurance.venue.fail.task.deletable"));
            }
            int[] allocTaskId = sceneTaskManageDBMapper.queryAllocTaskId(taskIds);
            int[] evaTaskId = sceneTaskManageDBMapper.queryEvaTaskId(taskIds);

            sceneTaskManageDBMapper.deleteTaskById(taskIds);
            sceneTaskManageDBMapper.deleteBitPackagesById(taskIds);
            // 删除泛场馆数据
            panVenueAllocDBMapper.deletePanVenueAllocResultByTaskId(taskIds);
            panVenueAllocDBMapper.deletePanVenueAllocTaskByTaskId(taskIds);
            sceneTaskManageDBMapper.deleteBackgroundUserGroupsById(taskIds);
            venueAllocTaskService.deleteTasks(String.valueOf(allocTaskId[0]));
            sceneTaskManagerUtils.deleteAllocTask(allocTaskId);
            sceneTaskManagerUtils.deleteEvaTask(evaTaskId);
            writeDeleteOperationLog(Constants.OPERATION_LEVEL_SUCCESS);
        } catch (

            DataAccessException ex) {
            writeDeleteOperationLog(Constants.OPERATION_LEVEL_FAILED);
            throw ex;
        }
    }

    private void writeDeleteOperationLog(int result) {
        String operation = LocaleUtil.getMessage("prs.scenealloc.deleteTask");
        String opResult = (result == Constants.OPERATION_LEVEL_SUCCESS
            ? LocaleUtil.getMessage("prs.venuealloc.success")
            : LocaleUtil.getMessage("prs.venuealloc.failed"));
        LogInfo logInfo = new LogInfo(operation, operation + opResult,
            LocaleUtil.getMessage("prs.tocallocvenue.scene.task.manage"),
            LocaleUtil.getMessage("prs.tocallocvenue.service.scene.task.manage"), result);
        OperationLogWriter.writeOperationLog(logInfo, AuditLogLevel.MAJOR.getValue(), OperationType.DELETE,
            AuditModule.MODULE_REPORT);
    }
}
